using namespace std;

int main() {
    const long long MOD = 1000000007;
    int n;
    cin >> n;
    long long a = 1, b = 2;  // f(1), f(2)
    if (n == 1) {
        cout << 1 << endl;
        return 0;
    }
    for (int i = 3; i <= n; i++) {
        long long c = (a + b) % MOD;
        a = b;
        b = c;
    }
    cout << b << endl;
    return 0;
}

